export class VersionedLruCache<T> { #items = new Map<string, { value: T; expiresAt: number }>(); readonly maximum: number; constructor(maximum = 1000) { if (maximum < 1) throw new Error('Cache maximum invalid'); this.maximum = maximum; } #key(namespace: string, version: string, key: string) { return `${namespace}:${version}:${key}`; } get(namespace: string, version: string, key: string, now = Date.now()): T | null { const full = this.#key(namespace, version, key); const item = this.#items.get(full); if (!item || item.expiresAt <= now) { this.#items.delete(full); return null; } this.#items.delete(full); this.#items.set(full, item); return structuredClone(item.value); } set(namespace: string, version: string, key: string, value: T, ttlMs: number, now = Date.now()): void { if (ttlMs < 1) throw new Error('Cache TTL invalid'); const full = this.#key(namespace, version, key); this.#items.delete(full); this.#items.set(full, { value: structuredClone(value), expiresAt: now + ttlMs }); while (this.#items.size > this.maximum) this.#items.delete(this.#items.keys().next().value!); } invalidateNamespace(namespace: string): void { for (const key of this.#items.keys()) if (key.startsWith(`${namespace}:`)) this.#items.delete(key); } get size() { return this.#items.size; } }
export function shardFor(universeId: string, recordId: string, shards: number): number { if (!Number.isInteger(shards) || shards < 1) throw new Error('Shard count invalid'); let hash = 2166136261; for (const char of `${universeId}\u001f${recordId}`) { hash ^= char.codePointAt(0)!; hash = Math.imul(hash, 16777619); } return (hash >>> 0) % shards; }
